import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        long number = Long.parseLong(reader.readLine());
        System.out.println(calculateOnes(number));
    }

    private static int getDigits(long n) {
        return (int) Math.log10(n) + 1;
    }

    private static long createOneSequence(int length) {
        long sequence = 1;
        for (int i = 1; i < length; i++) {
            sequence = sequence * 10 + 1;
        }
        return sequence;
    }

    private static long calculateOnes(long n) {
        if (n <= 6) return n;
        int digitsCount = getDigits(n);
        long baseSequence = createOneSequence(digitsCount);
        long total = baseSequence;
        int count = 0;
        long difference = n;

        while (total < n) {
            count++;
            difference = n - total;
            total += createOneSequence(digitsCount);
        }

        long result;
        if (count > 0)
            result = Math.min(count * digitsCount + calculateOnes(difference),
                              (count + 1) * digitsCount + calculateOnes(total - n));
        else
            result = (count + 1) * digitsCount + calculateOnes(total - n);

        long nextSequence = createOneSequence(digitsCount + 1);
        if (nextSequence - n < n)
            result = Math.min(result, digitsCount + 1 + calculateOnes(nextSequence - n));

        return result;
    }
}
